package store

type Store interface {
	Get(key string) string
}

package memory

type MemStore struct {
	Data map[string]string
}

func (m *MemStore) Get(key string) string {
	return m.Data[key]
}

package service

import "evaltask/store"

func LookupOrDefault(s store.Store, key, fallback string) string {
	if v := s.Get(key); v != "" {
		return v
	}

	return fallback
}

package service

import "testing"

type mockStore map[string]string

func (m mockStore) Get(key string) string {
	return m[key]
}

func TestLookupOrDefault(t *testing.T) {
	s := mockStore{"env": "prod", "empty": ""}
	if got := LookupOrDefault(s, "env", "dev"); got != "prod" {
		t.Fatalf("got %q, want prod", got)
	}
	if got := LookupOrDefault(s, "missing", "dev"); got != "dev" {
		t.Fatalf("got %q, want dev", got)
	}
}

package app

import (
	"evaltask/memory"
	"evaltask/service"
)

func ReadSetting(cfg map[string]string, key string) string {
	return service.LookupOrDefault(&memory.MemStore{Data: cfg}, key, "default")
}

package app

import "testing"

func TestReadSetting(t *testing.T) {
	if got := ReadSetting(map[string]string{"mode": "fast"}, "mode"); got != "fast" {
		t.Fatalf("got %q, want fast", got)
	}
}
